const rows=[{"code":"CHECKSUM_MISMATCH","title":{"en":"Checksum mismatch","ru":"Несовпадение checksum"},"remediation":{"en":"Recompute SHA-256 from the received bytes and compare with the signed manifest.","ru":"Пересчитайте SHA-256 полученного файла и сравните с подписанным манифестом."},"scope":{"en":"Delivery integrity","ru":"Целостность передачи"}},{"code":"MISSING_LOCALE_OUTPUT","title":{"en":"Missing locale output","ru":"Нет локализованного выхода"},"remediation":{"en":"Compare required locales with delivered audio, subtitle and metadata outputs.","ru":"Сравните обязательные локали с переданными аудио, субтитрами и метаданными."},"scope":{"en":"Localization","ru":"Локализация"}},{"code":"UNSAFE_RELATIVE_PATH","title":{"en":"Unsafe relative path","ru":"Небезопасный относительный путь"},"remediation":{"en":"Remove traversal segments, absolute roots and reserved characters before packaging.","ru":"Удалите traversal-сегменты, абсолютные корни и запрещённые символы до упаковки."},"scope":{"en":"Package safety","ru":"Безопасность пакета"}},{"code":"RIGHTS_WINDOW_EXPIRED","title":{"en":"Rights window expired","ru":"Срок прав истёк"},"remediation":{"en":"Stop distribution and confirm a new territory, channel and end date with the rights owner.","ru":"Остановите дистрибуцию и подтвердите новую территорию, канал и дату с правообладателем."},"scope":{"en":"Rights","ru":"Права"}},{"code":"CAPTION_TIMING_OVERLAP","title":{"en":"Caption timing overlap","ru":"Пересечение таймингов субтитров"},"remediation":{"en":"Move cue boundaries so each end precedes the next start, then rerun timing validation.","ru":"Скорректируйте границы cues так, чтобы конец предшествовал следующему началу, затем повторите проверку."},"scope":{"en":"Captions","ru":"Субтитры"}},{"code":"APPROVAL_CHAIN_INCOMPLETE","title":{"en":"Approval chain incomplete","ru":"Цепочка согласований неполна"},"remediation":{"en":"Record explicit decisions for brief, creative, offline and master stages.","ru":"Запишите явные решения для этапов brief, creative, offline и master."},"scope":{"en":"Approval","ru":"Согласование"}},{"code":"IMAGE_SEQUENCE_GAP","title":{"en":"Image sequence gap","ru":"Пропуск в image sequence"},"remediation":{"en":"Locate the missing frame number and restore or document the intentional gap.","ru":"Найдите отсутствующий номер кадра и восстановите его либо задокументируйте намеренный пропуск."},"scope":{"en":"Image sequence","ru":"Последовательность кадров"}},{"code":"AUDIO_CHANNEL_DUPLICATE","title":{"en":"Duplicate audio channel","ru":"Дублирующийся аудиоканал"},"remediation":{"en":"Assign unique contiguous channel numbers and declare a label for every channel.","ru":"Назначьте уникальные последовательные номера и label каждому каналу."},"scope":{"en":"Audio metadata","ru":"Метаданные аудио"}},{"code":"MANIFEST_DUPLICATE_ID","title":{"en":"Duplicate manifest identifier","ru":"Дублирующийся ID манифеста"},"remediation":{"en":"Generate one stable identifier per asset and update every dependent reference.","ru":"Создайте один стабильный ID на актив и обновите все зависимые ссылки."},"scope":{"en":"Manifest","ru":"Манифест"}},{"code":"ARCHIVE_ROLE_MISSING","title":{"en":"Required archive role missing","ru":"Нет обязательной роли архива"},"remediation":{"en":"Add master, manifest and rights records with valid SHA-256 values before archiving.","ru":"Добавьте master, manifest и запись прав с корректными SHA-256 до архивирования."},"scope":{"en":"Archive","ru":"Архив"}}];const lang=document.documentElement.lang==='ru'?'ru':'en';const select=document.getElementById('error-code'),output=document.getElementById('output');function render(){const e=rows.find(x=>x.code===select.value);output.textContent=JSON.stringify({found:!!e,code:e?.code,title:e?.title[lang],scope:e?.scope[lang],remediation:e?.remediation[lang],publisher:'SHAR Production',website:'https://sharprod.com/'},null,2)}document.getElementById('explore').addEventListener('click',render);render();
